import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class KeyValueStore<K, V> {
    private final ConcurrentHashMap<K, V> store = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, AtomicLong> accessCounts =
            new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, AtomicLong> lastAccessTimes =
            new ConcurrentHashMap<>();
    private final ConcurrentHashMap<Class<?>, AtomicLong> typeCounts =
            new ConcurrentHashMap<>();

    private final Object typeCountsLock = new Object();

    public void put(K key, V value) {
        validateKey(key);

        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }

        synchronized (typeCountsLock) {
            V previousValue = store.put(key, value);

            if (previousValue != null) {
                decrementTypeCount(previousValue.getClass());
            }

            typeCounts
                    .computeIfAbsent(value.getClass(), ignored -> new AtomicLong())
                    .incrementAndGet();
        }
    }

    public V get(K key) {
        validateKey(key);

        accessCounts
                .computeIfAbsent(key, ignored -> new AtomicLong())
                .incrementAndGet();

        long currentTime = System.currentTimeMillis();
        lastAccessTimes
                .computeIfAbsent(key, ignored -> new AtomicLong())
                .accumulateAndGet(currentTime, Math::max);

        return store.get(key);
    }

    public long getAccessCount(K key) {
        validateKey(key);

        AtomicLong count = accessCounts.get(key);
        return count == null ? 0L : count.get();
    }

    public long getLastAccessTime(K key) {
        validateKey(key);

        AtomicLong lastAccessTime = lastAccessTimes.get(key);
        return lastAccessTime == null ? 0L : lastAccessTime.get();
    }

    public long getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        synchronized (typeCountsLock) {
            AtomicLong count = typeCounts.get(type);
            return count == null ? 0L : count.get();
        }
    }

    private void decrementTypeCount(Class<?> type) {
        AtomicLong count = typeCounts.get(type);

        if (count != null && count.decrementAndGet() == 0L) {
            typeCounts.remove(type, count);
        }
    }

    private void validateKey(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
    }
}

