import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class KeyValueStore<K, V> {
    private final ConcurrentHashMap<K, V> store = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, AtomicLong> accessCounts =
            new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, AtomicLong> lastAccessTimes =
            new ConcurrentHashMap<>();
    private final ConcurrentHashMap<Class<?>, AtomicLong> typeCounts =
            new ConcurrentHashMap<>();

    private final Object dataLock = new Object();

    public void put(K key, V value) {
        validateKey(key);
        validateValue(value);

        synchronized (dataLock) {
            V previousValue = store.put(key, value);

            if (previousValue != null) {
                decrementTypeCount(previousValue.getClass());
            }

            incrementTypeCount(value.getClass());
        }
    }

    public void putAll(Map<? extends K, ? extends V> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries cannot be null");
        }

        synchronized (dataLock) {
            for (Map.Entry<? extends K, ? extends V> entry : entries.entrySet()) {
                K key = entry.getKey();
                V value = entry.getValue();

                validateKey(key);
                validateValue(value);

                V previousValue = store.put(key, value);

                if (previousValue != null) {
                    decrementTypeCount(previousValue.getClass());
                }

                incrementTypeCount(value.getClass());
            }
        }
    }

    public V get(K key) {
        validateKey(key);

        accessCounts
                .computeIfAbsent(key, ignored -> new AtomicLong())
                .incrementAndGet();

        lastAccessTimes
                .computeIfAbsent(key, ignored -> new AtomicLong())
                .set(System.currentTimeMillis());

        return store.get(key);
    }

    public long getAccessCount(K key) {
        validateKey(key);

        AtomicLong count = accessCounts.get(key);
        return count == null ? 0L : count.get();
    }

    public long getLastAccessTime(K key) {
        validateKey(key);

        AtomicLong time = lastAccessTimes.get(key);
        return time == null ? 0L : time.get();
    }

    public long getTypeCount(Class<?> type) {
        validateType(type);

        AtomicLong count = typeCounts.get(type);
        return count == null ? 0L : count.get();
    }

    public Set<K> findKeysByType(Class<?> type) {
        validateType(type);

        Set<K> matchingKeys = new HashSet<>();

        for (Map.Entry<K, V> entry : store.entrySet()) {
            if (entry.getValue().getClass().equals(type)) {
                matchingKeys.add(entry.getKey());
            }
        }

        return matchingKeys;
    }

    public Statistics<K> computeStatistics() {
        synchronized (dataLock) {
            K keyWithMaxAccess = null;
            long maximumAccessCount = 0L;

            for (K key : store.keySet()) {
                AtomicLong count = accessCounts.get(key);
                long currentCount = count == null ? 0L : count.get();

                if (keyWithMaxAccess == null || currentCount > maximumAccessCount) {
                    keyWithMaxAccess = key;
                    maximumAccessCount = currentCount;
                }
            }

            Map<Class<?>, Long> typeDistribution = new HashMap<>();
            for (Map.Entry<Class<?>, AtomicLong> entry : typeCounts.entrySet()) {
                typeDistribution.put(entry.getKey(), entry.getValue().get());
            }

            long estimatedMemoryUsage = store.size() * 32L;

            return new Statistics<>(
                    store.size(),
                    keyWithMaxAccess,
                    typeDistribution,
                    estimatedMemoryUsage
            );
        }
    }

    public void clear() {
        synchronized (dataLock) {
            store.clear();
            accessCounts.clear();
            lastAccessTimes.clear();
            typeCounts.clear();
        }
    }

    private void incrementTypeCount(Class<?> type) {
        typeCounts
                .computeIfAbsent(type, ignored -> new AtomicLong())
                .incrementAndGet();
    }

    private void decrementTypeCount(Class<?> type) {
        AtomicLong count = typeCounts.get(type);

        if (count != null && count.decrementAndGet() == 0L) {
            typeCounts.remove(type, count);
        }
    }

    private void validateKey(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
    }

    private void validateValue(V value) {
        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }
    }

    private void validateType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
    }

    public static final class Statistics<K> {
        private final int totalEntries;
        private final K keyWithMaxAccess;
        private final Map<Class<?>, Long> typeDistribution;
        private final long estimatedMemoryUsage;

        private Statistics(
                int totalEntries,
                K keyWithMaxAccess,
                Map<Class<?>, Long> typeDistribution,
                long estimatedMemoryUsage
        ) {
            this.totalEntries = totalEntries;
            this.keyWithMaxAccess = keyWithMaxAccess;
            this.typeDistribution = Collections.unmodifiableMap(
                    new HashMap<>(typeDistribution)
            );
            this.estimatedMemoryUsage = estimatedMemoryUsage;
        }

        public int getTotalEntries() {
            return totalEntries;
        }

        public K getKeyWithMaxAccess() {
            return keyWithMaxAccess;
        }

        public Map<Class<?>, Long> getTypeDistribution() {
            return typeDistribution;
        }

        public long getEstimatedMemoryUsage() {
            return estimatedMemoryUsage;
        }
    }
}

