import java.util.ArrayList;
import java.util.List;

enum HitResult {
    HIT,
    MISS,
    SUNK
}

public class NavalBattleAdapter {
    private final List<String> shipPositions;
    private final List<String> attackPositions;

    public NavalBattleAdapter() {
        this.shipPositions = new ArrayList<>();
        this.attackPositions = new ArrayList<>();
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates == null || coordinates.isEmpty()) {
            throw new IllegalArgumentException(
                    "Ship coordinates must not be null or empty."
            );
        }

        shipPositions.addAll(coordinates);
    }

    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null || coordinate.isEmpty()) {
            throw new IllegalArgumentException(
                    "Attack coordinate must not be null or empty."
