public final class Company {
    private static final Company INSTANCE = new Company();

    private final List<Employee> allEmployees;
    private int employeeCounter;
    private Manager ceo;
    private String companyName;

    private Company() {
        allEmployees = new ArrayList<>();
        employeeCounter = 1;
    }

