    public synchronized void hireCEO(Manager manager) {
        if (ceo != null) {
            throw new IllegalStateException("A CEO has already been hired.");
        }

        if (manager == null) {
            throw new IllegalArgumentException("CEO cannot be null.");
        }

        manager.setId("EMP-" + employeeCounter++);
        ceo = manager;
        allEmployees.add(manager);
    }

    public synchronized Manager getCEO() {
        return ceo;
    }

    public synchronized void hireEmployee(Manager manager, Employee employee) {
        if (manager == null || !allEmployees.contains(manager)) {
            throw new IllegalArgumentException(
                    "The manager must already be an employee of the company."
            );
        }

        if (employee == null) {
            throw new IllegalArgumentException("Employee cannot be null.");
        }

        employee.setId("EMP-" + employeeCounter++);
        manager.addSubordinate(employee);
        allEmployees.add(employee);
    }

    public synchronized int getEmployeeCount() {
        return allEmployees.size();
    }

    public synchronized List<Employee> getAllEmployees() {
        return new ArrayList<>(allEmployees);
    }

    public synchronized void setCompanyName(String name) {
        companyName = name;
    }

    public synchronized String getCompanyName() {
        return companyName;
    }
}
