        if (!Files.isDirectory(this.directory)) {
            throw new IllegalArgumentException(
                    "Provided path is not a directory: " + directoryPath
            );
        }
    }

    public Map<String, Object> processFiles() {
        long fileCount = 0;
        long totalSize = 0L;
        long largestSize = -1L;
        String largestFile = "N/A";
        Map<String, Integer> wordFrequency = new LinkedHashMap<>();

        try (Stream<Path> paths = Files.walk(directory)) {
            for (Path path : (Iterable<Path>) paths::iterator) {
                if (Files.isRegularFile(path)) {
                    long fileSize = Files.size(path);

                    fileCount++;
                    totalSize += fileSize;

                    if (fileSize > largestSize) {
                        largestSize = fileSize;
                        largestFile = path.getFileName().toString();
                    }

                    processFileContent(path, wordFrequency);
                }
            }
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to process files", e);
        }

        Map<String, Object> results = new LinkedHashMap<>();
        results.put("fileCount", fileCount);
        results.put("totalSize", totalSize);
        results.put("largestFile", largestFile);
        results.put(
                "wordFrequency",
                wordFrequency.isEmpty()
                        ? Collections.emptyMap()
                        : sortByValue(wordFrequency)
        );

        return results;
    }

    private void processFileContent(
            Path file,
            Map<String, Integer> wordFrequency
    ) {
        try {
            String content = new String(
                    Files.readAllBytes(file),
                    StandardCharsets.UTF_8
            );

            for (String word : content.split("\\s+")) {
                String normalizedWord = word
                        .replaceAll("[^a-zA-Z]", "")
                        .toLowerCase(Locale.ROOT);

                if (!normalizedWord.isEmpty()) {
                    wordFrequency.merge(normalizedWord, 1, Integer::sum);
                }
            }
        } catch (IOException e) {
            throw new UncheckedIOException(
                    "Failed to read file: " + file,
                    e
            );
        }
    }

    private Map<String, Integer> sortByValue(Map<String, Integer> map) {
        Map<String, Integer> sortedMap = new LinkedHashMap<>();

        map.entrySet()
                .stream()
                .sorted(
