    private void inOrderRec(Node<T> node, List<T> result) {
        if (node == null) {
            return;
        }

        inOrderRec(node.left, result);
        result.add(node.data);
        inOrderRec(node.right, result);
    }
}

class AdvancedTreeLoader {
    public <T extends Comparable<T>> void load(
            BinaryTree<T> tree,
            List<T> data,
            boolean shouldSort,
            boolean allowDuplicates) {

        if (!allowDuplicates) {
            List<T> sortedData = new ArrayList<>(data);
            Collections.sort(sortedData);

            for (int i = 1; i < sortedData.size(); i++) {
                if (sortedData.get(i - 1).compareTo(sortedData.get(i)) == 0) {
                    throw new IllegalArgumentException(
                            "Duplicate elements found: " + sortedData.get(i)
                    );
                }
            }
        }

        if (shouldSort) {
            List<T> sortedData = new ArrayList<>(data);
            Collections.sort(sortedData);
            loadBalanced(tree, sortedData, 0, sortedData.size() - 1);
        } else {
            for (T value : data) {
                tree.insert(value);
            }
        }
    }

    private <T extends Comparable<T>> void loadBalanced(
            BinaryTree<T> tree,
            List<T> data,
            int start,
            int end) {

        if (start > end) {
            return;
        }

        int middle = start + (end - start) / 2;
        tree.insert(data.get(middle));

        loadBalanced(tree, data, start, middle - 1);
        loadBalanced(tree, data, middle + 1, end);
    }
}
