import java.util.*;

class GraphAnalyzer {
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        if (graph == null || graph.length == 0) {
            throw new IllegalArgumentException("Graph must not be null or empty.");
        }

        int n = graph.length;

        for (int i = 0; i < n; i++) {
            if (graph[i] == null || graph[i].length != n) {
                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
            }

            for (int j = 0; j < n; j++) {
                if (graph[i][j] < 0 && graph[i][j] != -1) {
                    throw new IllegalArgumentException("Dijkstra's algorithm requires non-negative edge weights.");
                }
            }
        }

        if (source < 0 || source >= n) {
            throw new IllegalArgumentException("Source vertex is out of range.");
        }

        int[] distances = new int[n];
        int[] previous = new int[n];
        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(previous, -1);

        distances[source] = 0;

        PriorityQueue<Vertex> queue = new PriorityQueue<>(
                Comparator.comparingInt(vertex -> vertex.distance)
        );
        queue.offer(new Vertex(source, 0));

        while (!queue.isEmpty()) {
            Vertex current = queue.poll();

            if (current.distance != distances[current.index]) {
                continue;
            }

            for (int neighbor = 0; neighbor < n; neighbor++) {
                int weight = graph[current.index][neighbor];

                // Zero and -1 represent the absence of an edge.
                if (weight <= 0 || weight == Integer.MAX_VALUE) {
                    continue;
                }

                if (current.distance > Integer.MAX_VALUE - weight) {
                    continue;
                }

                int newDistance = current.distance + weight;

                if (newDistance < distances[neighbor]) {
                    distances[neighbor] = newDistance;
                    previous[neighbor] = current.index;
                    queue.offer(new Vertex(neighbor, newDistance));
                }
            }
        }

        Map<Integer, List<Integer>> paths = new LinkedHashMap<>();
        for (int vertex = 0; vertex < n; vertex++) {
            paths.put(vertex, buildPath(previous, source, vertex));
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("distances", distances);
        result.put("paths", paths);
        return result;
    }

    private static List<Integer> buildPath(int[] prev, int source, int target) {
        List<Integer> path = new ArrayList<>();

        if (target < 0 || target >= prev.length) {
            return path;
        }

        int current = target;
        while (current != -1) {
            path.add(current);

            if (current == source) {
                Collections.reverse(path);
                return path;
            }

            current = prev[current];
        }

        return new ArrayList<>();
    }

    private static class Vertex {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
}

